const React=require('react'),{createRoot}=require('react-dom/client');
const {CompanionFacebookAction}=require('../../components/inbox/companion-facebook-action.tsx');
const root=createRoot(document.getElementById('root')),checks=[],calls=[],popups=[];
let release,mode='exact';const props={pageId:'12345',threadId:'98765',businessId:'b1',conversationId:'c1',navigationOnly:true,compact:true};
const link='https://business.facebook.com/latest/inbox/all?asset_id=12345&selected_item_id=54321&thread_type=FB_MESSAGE';
window.open=()=>{const p={closed:false,opener:{},document:document.implementation.createHTMLDocument(),location:{href:'about:blank',replace(value){this.href=value;}},close(){this.closed=true;}};popups.push(p);return p;};
window.fetch=(url,options)=>{calls.push({url,options});return new Promise(r=>release=()=>r(new Response(JSON.stringify({success:true,businessId:props.businessId,conversationId:props.conversationId,pageId:props.pageId,recipientId:props.threadId,
 navigationAvailable:mode==='exact',linkSource:'meta_conversations_api',conversationLink:mode==='exact'?link:null,
 pageInboxUrl:mode==='unsafe'?'https://evil.test/':`https://business.facebook.com/latest/inbox/all?asset_id=${props.pageId}`}))));};
const pause=()=>new Promise(r=>setTimeout(r,60)),check=(name,condition)=>{if(!condition)throw Error(name);checks.push(name);};
const render=()=>root.render(React.createElement(CompanionFacebookAction,props));
(async()=>{try{render();await pause();check('no request on render',calls.length===0);document.querySelector('button').click();await pause();check('click starts exactly one read-only request',calls.length===1&&new URL(calls[0].url,'https://fixture.local').searchParams.get('lookup')==='navigation'&&!calls[0].options.method);document.querySelector('button').click();check('busy click does not duplicate',calls.length===1);release();await pause();check('verified provider URL navigates isolated tab with no opener',popups[0].location.href===link&&popups[0].opener===null);
 mode='missing';document.querySelector('button').click();await pause();release();await pause();check('missing exact URL closes loading tab without redirect',popups[1].closed&&popups[1].location.href==='about:blank');check('fallback explicitly names Page inbox',document.querySelector('a').textContent==='Open Page inbox'&&document.querySelector('a').href==='https://business.facebook.com/latest/inbox/all?asset_id=12345');
 mode='unsafe';document.querySelector('button').click();await pause();release();await pause();check('unsafe fallback cannot navigate or produce a link',!document.querySelector('a')&&popups[2].closed);
 mode='exact';document.querySelector('button').click();await pause();const oldRelease=release;props.conversationId='c2';props.threadId='77777';render();await pause();check('switch aborts pending lookup and closes untouched tab',calls.at(-1).options.signal.aborted&&popups[3].closed);oldRelease();await pause();check('late response cannot navigate after switch',popups[3].location.href==='about:blank'&&!document.querySelector('[role="alert"]'));document.getElementById('result').textContent=JSON.stringify({passed:true,checks});}catch(error){document.getElementById('result').textContent=JSON.stringify({passed:false,error:error.message,checks});}})();
